import {
  ModalOverlay,
  CloseButton,
  ModalButton,
  ModalContent,
  ModalDescription,
  ModalDetails,
  ModalImage,
  ModalTitle
} from './styles'

import fechar from '../../assets/images.nova/close.svg' // Importe uma imagem para o botão de fechar

type ModalProps = {
  isOpen: boolean
  onClose: () => void
  image: string
  title: string
  description: string
}

const Modal = ({ isOpen, closeModal }) => {
  useEffect(() => {
    // Bloquear rolagem ao abrir o modal
    if (isOpen) {
      document.body.style.overflow = 'hidden';
    } else {
      document.body.style.overflow = 'auto'; // Restaura a rolagem quando o modal é fechado
    }

    // Limpeza ao desmontar o componente para evitar problemas de rolagem após fechar o modal
    return () => {
      document.body.style.overflow = 'auto';
    }
  }, [isOpen]); // O efeito será acionado sempre que 'isOpen' mudar

  return isOpen ? (
    <ModalOverlay>
      <ModalContent>
        <ModalImage src="imagem_exemplo.jpg" alt="Imagem do Modal" />
        <ModalDetails>
          <ModalTitle>Detalhes do Produto</ModalTitle>
          <ModalDescription>
            Descrição do produto aqui.
          </ModalDescription>
          <ModalButton onClick={closeModal}>Fechar</ModalButton>
        </ModalDetails>
        <CloseButton onClick={closeModal}>
          <img src="close_icon.svg" alt="Fechar" />
        </CloseButton>
      </ModalContent>
    </ModalOverlay>
  ) : null;
}

export default Modal;
